window.AUTH=window.AUTH||{};window.AUTH["19-292"]={"d":"19-292","id":"2020/19-292","n":"Torres v. Madrid","briefs":[{"k":"petitioner","label":"Brief of petitioner Roxanne Torres","date":"2020-01-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-292/130661/20200131165910890_200111a%20Merits%20Brief%20for%20e-filing.pdf","side":"pet","n":61},{"k":"united-states","label":"Brief amicus curiae of the United States","date":"2020-02-07","url":"https://www.supremecourt.gov/DocketPDF/19/19-292/132389/20200207185933657_19-292tsacUnitedStates.pdf","side":"us","n":28},{"k":"respondent","label":"Brief of respondents Janice Madrid, et al.","date":"2020-03-02","url":"https://www.supremecourt.gov/DocketPDF/19/19-292/134663/20200302161610077_19-292%20Torres%20v%20Madrid%20Brief%20of%20Respondents.pdf","side":"res","n":150},{"k":"reply","label":"Reply of petitioner Roxanne Torres","date":"2020-03-25","url":"https://www.supremecourt.gov/DocketPDF/19/19-292/139094/20200325122335820_200308a%20Reply%20for%20efiling.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-292_21p3.pdf","tr":true,"items":[{"t":"case","label":"Acevedo v. Canterbury","cite":"457 F.3d 721","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/457/721/","sum":"Rejecting the argument that “physical force alone cannot constitute a seizure” because “the Supreme Court has held otherwise”.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"Atwater v. City of Lago Vista","cite":"532 U.S. 318","y":2001,"id":"2000/99-1408","sc":1,"op":1,"ar":1,"sum":"The Court held that the Fourth Amendment does not forbid a warrantless arrest for a minor criminal offense, such as a misdemeanor seatbelt violation punishable only by a fine. \"If an officer has probable cause to believe that an individual has committed even a very minor criminal offense in his presence, he may, without violating the Fourth Amendment, arrest the offender,\" wrote Justice Souter for the Court.","sumSrc":"Oyez","by":{"0":"17, 22, 24","2":"45"}},{"t":"case","label":"Brendlin v. California","cite":"551 U.S. 249","y":2007,"id":"2006/06-8120","sc":1,"op":1,"sum":"The Court held that when a vehicle is stopped at a traffic stop, the passenger as well as the driver is seized within the meaning of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"10, 34, 35","1":"12, 13, 16","2":"10, 11, 13, 31, 45"}},{"t":"case","label":"Brice v. City of York","cite":"528 F. Supp. 2d 504","y":2007,"court":"M.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/528/504/","sum":"Recognizing that accidental conduct cannot effect a seizure and collecting cases.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Brooks v. Gaenzle","cite":"614 F.3d 1213","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/1213/","op":2,"sum":"Noting that, while the Defendant Deputy’s “gunshot may have intentionally struck” plaintiff, “it clearly did not terminate his movement or otherwise cause the government to have physical control over him” and thus, plaintiff failed to show that the Defendants’ “alleged conduct violated a constitutional right by means of ‘seizure’ ”.","sumSrc":"brief:2","by":{"0":"38","1":"5, 6, 15, 16","2":"11, 17, 22, 31, 40"}},{"t":"case","label":"Brower v. County of Inyo","cite":"489 U.S. 593","y":1989,"id":"1988/87-248","sc":1,"op":5,"sum":"The Court held that a police roadblock could constitute an illegal seizure under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"10, 32, 33, 34, 38, 40","1":"11, 12, 13, 16, 20","2":"passim","3":"14"}},{"t":"case","label":"Brown v. Texas","cite":"443 U.S. 47","y":1979,"id":"1978/77-6673","sc":1,"sum":"The Court held that the Fourth Amendment covers all police seizures, even those as brief as preventing a person from walking away. The Fourth Amendment requires that such seizures be based on specific and objective facts that create a compelling public interest in the seizure that outweighs the individual’s expectation of privacy.","sumSrc":"Oyez","by":{"0":"27","3":"16"}},{"t":"case","label":"Byrd v. United States","cite":"138 S. Ct. 1518","y":2018,"id":"2017/16-1371","sc":1,"sum":"The Court held that a driver of a rental car who has permission to drive the car but is not listed as an authorized driver on the rental agreement has a reasonable expectation of privacy in the rental car.","sumSrc":"Oyez","by":{"0":"36","2":"36, 37"}},{"t":"case","label":"California v. Hodari D.","cite":"499 U.S. 621","y":1991,"id":"1990/89-1632","sc":1,"op":16,"sum":"The Supreme Court held that a Fourth Amendment seizure requires some sort of physical force with lawful authority, or submission to an assertion of authority. Hodari had not been touched when he discarded the cocaine, and had not submitted to authority because he was still attempting to escape.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Carlson v. Bukovic","cite":"621 F.3d 610","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/621/610/","by":{"0":"40","2":"13"}},{"t":"case","label":"Carpenter v. United States","cite":"138 S. Ct. 2206","y":2018,"id":"2017/16-402","sc":1,"op":1,"sum":"The Court held that the warrantless seizure and search of cell phone records revealing the location and movements of a cell phone user over the course of 127 days violates the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"15","2":"35"}},{"t":"case","label":"Carr v. Tatangelo","cite":"338 F.3d 1259","y":2003,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/338/1259/","by":{"0":"37"}},{"t":"case","label":"Carrillo-Ortiz v. N.M. State Police","cite":"2019 WL 4393989","y":2019,"court":"D.N.M. Sept. 13","by":{"0":"45"}},{"t":"case","label":"Carroll v. United States","cite":"267 U.S. 132","y":1925,"id":"scdb/1924-088","sc":1,"op":1,"sum":"1. The legislative history of § 6 of the act supplemental. to the National Prohibition Act, November 23, 1921, c. 134, 42 Stat. 223, which makes it a misdemeanor for any officer of the United States to search a private dwelling without a search warrant or to search any other building or property without a search warrant, ma-liciotísly aíid without reasonable cause, shows clearly the intent of Congress to make a …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15, 46"}},{"t":"case","label":"Childress v. City of Arapaho","cite":"210 F.3d 1154","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/210/1154/","by":{"0":"7","1":"5","2":"28"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"42","1":"22"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"op":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"22","3":"13"}},{"t":"case","label":"Elkins v. United States","cite":"364 U.S. 206","y":1960,"id":"1959/126","sc":1,"sum":"1. Evidence obtained by state officers during a search which, if conducted by federal officers, would have violated the defendant's immunity from unreasonable searches and seizures under the Fourth Amendment is inadmissible over the defendant's timely objection in a federal criminal trial, even when there was no participation by federal officers in the search and seizure.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 41","1":"20"}},{"t":"case","label":"Florida v. Bostick","cite":"501 U.S. 429","y":1991,"id":"1990/89-1717","sc":1,"sum":"The Court held that in the absence of intimidation or harassment, Bostick could have refused the search request. Moreover, the fact that he knew the search would produce contraband had no bearing on whether his consent was voluntarily obtained. The test of whether a \"reasonable person\" felt free to decline or terminate a search presupposes his or her innocence.","sumSrc":"Oyez","by":{"0":"34","1":"13","2":"9, 10, 13, 47"}},{"t":"case","label":"Florida v. White","cite":"526 U.S. 559","y":1999,"id":"1998/98-223","sc":1,"sum":"The Court held that the Fourth Amendment does not require the police to obtain a warrant before seizing an automobile from a public place when they have probable cause to believe that it is forfeitable contraband.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"0":"6, 27, 41","1":"9, 21","2":"2, 25","3":"21"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Henry v. United States","cite":"361 U.S. 98","y":1959,"id":"1959/17","sc":1,"sum":"On the record -in this case, the officers did not have probable cause for the arrest when they stopped \"he car; the search was illegal; the articles seized were not admissible in evidence; and the conviction is reversed. Pp. 98-104. 259 F. 2d 725, reveijed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","2":"43","3":"9"}},{"t":"case","label":"Henson v. United States","cite":"55 A.3d 859","y":2012,"court":"D.C.","url":"https://www.courtlistener.com/c/A.3d/55/859/","op":1,"by":{"0":"43, 38"}},{"t":"case","label":"Holland v. Krogstad","cite":"2012 WL 13076246","y":2012,"court":"D.N.M. Aug. 23","by":{"0":"44"}},{"t":"case","label":"Kyllo v. United States","cite":"533 U.S. 27","y":2001,"id":"2000/99-8508","sc":1,"op":1,"sum":"The Court found the use of thermal-imaging to detect areas of high heat in one's private home was a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Ludwig v. Anderson","cite":"54 F.3d 465","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/54/465/","by":{"0":"37"}},{"t":"case","label":"Lytle v. Bexar County","cite":"560 F.3d 404","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/560/404/","by":{"0":"45","2":"29"}},{"t":"case","label":"Martinez v. Nygaard","cite":"831 F.2d 822","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/831/822/","by":{"0":"40"}},{"t":"case","label":"Maryland v. King","cite":"569 U.S. 435","y":2013,"id":"2012/12-207","sc":1,"ar":1,"sum":"The Court found that taking a DNA sample from people who are arrested, but not yet convicted, of a serious crime is not a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"10, 28, 29, 41, 42"}},{"t":"case","label":"McCracken v. Ansley","cite":"35 S.C.L. 1","y":1849,"court":"S.C. Ct. App.","url":"https://www.courtlistener.com/c/S.C.L./35/1/","by":{"0":"22","3":"5"}},{"t":"case","label":"Mullenix v. Luna","cite":"136 S. Ct. 305","y":2015,"id":"2015/14-1143","sc":1,"sum":"The Court determined that a trooper was entitled to qualified immunity for his actions in the context of the situation he faced.","sumSrc":"Oyez","by":{"0":"12, 38, 42","1":"22"}},{"t":"case","label":"Nelson v. City of Davis","cite":"685 F.3d 867","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/685/867/","by":{"0":"37"}},{"t":"case","label":"People v. McLean","cite":"36 N.W. 231","y":1888,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./36/231/","by":{"0":"22"}},{"t":"case","label":"Pike v. Hanson","cite":"9 N.H. 491","y":1838,"url":"https://www.courtlistener.com/c/N.H./9/491/","by":{"0":"22"}},{"t":"case","label":"Plumhoff v. Rickard","cite":"572 U.S. 765","y":2014,"id":"2013/12-1117","sc":1,"sum":"The Court held that police using deadly force to prevent a crime endangering the general public are granted qualified immunity.","sumSrc":"Oyez","by":{"0":"38","1":"21, 22","2":"19","3":"15"}},{"t":"case","label":"Riley v. California","cite":"573 U.S. 373","y":2014,"id":"2013/13-132","sc":1,"op":1,"sum":"The Court found that the San Diego Police Department's search of an arrested gang member's cell phone pictures without a warrant violated the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Roberson v. State","cite":"43 Fla. 156","y":1901,"url":"https://www.courtlistener.com/c/Fla./43/156/","by":{"0":"22","3":"8"}},{"t":"case","label":"Schmerber v. California","cite":"384 U.S. 757","y":1966,"id":"1965/658","sc":1,"sum":"Justice Brennan argued for a 5-4 majority that the protection against self-incrimination applied specifically to compelled communications or testimony. Since the results of the blood test were neither \"testimony nor evidence relating to some communicative act or writing by the petitioner, it was not inadmissible on privilege grounds.\".","sumSrc":"Oyez","by":{"0":"27","2":"35, 36"}},{"t":"case","label":"State v. Garcia","cite":"217 P.3d 1032","y":2009,"court":"N.M.","url":"https://www.courtlistener.com/c/P.3d/217/1032/","sum":"Holding that defendant was seized the moment he was sprayed with pepper spray because “[u]nlike assertion-of-authority cases, there is no need for a defendant to demonstrate submission in cases of physical force”.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"Tennessee v. Garner","cite":"471 U.S. 1","y":1985,"id":"1984/83-1035","sc":1,"op":2,"sum":"The Court ruled that a statute authorizing use of deadly force to prevent the escape of a fleeing suspected felon violates the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"28, 34, 41","1":"17","2":"passim"}},{"t":"case","label":"Terry v. Ohio","cite":"392 U.S. 1","y":1968,"id":"1967/67","sc":1,"op":3,"ar":1,"sum":"The Court found that police using a \"stop and frisk\" procedure are within their constitutional bounds as officers of the law.","sumSrc":"Oyez","by":{"0":"10, 27, 28, 35, 36, 40, 41","1":"7, 10, 17, 18, 21","2":"passim"}},{"t":"case","label":"Tolan v. Cotton","cite":"572 U.S. 650","y":2014,"id":"2013/13-551","sc":1,"op":1,"sum":"A case which the Court remanded concerning whether or not a police officer had the right to shoot a man outside of his home when the officer believed him to be in possession of a stolen car.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"United States v. Benner","cite":"24 F. Cas. 1084","y":1830,"court":"C.C.E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./24/1084/","op":2,"by":{"0":"22","3":"10, 11"}},{"t":"case","label":"United States v. Dupree","cite":"617 F.3d 724","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/617/724/","sum":"Noting the government’s “concession” that suspect was seized when officer grasped him momentarily before he fled.","sumSrc":"brief:0","by":{"0":"37, 43","2":"26"}},{"t":"case","label":"United States v. Jacobsen","cite":"466 U.S. 109","y":1984,"id":"1983/82-1167","sc":1,"op":1,"sum":"The Court held that the initial inspection by the DEA agent did not violate the Fourth Amendment because it remained within the scope of the previous search conducted by private agents. Once the agents gained enough information about the package to believe it contained contraband, the warrantless seizure of the package and its contents was not unreasonable.","sumSrc":"Oyez","by":{"0":"39","1":"16, 18","2":"33"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"op":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"9, 14, 15, 16, 27, 36, 37","2":"34, 35","3":"9, 13"}},{"t":"case","label":"United States v. Jones","cite":"625 F.3d 766","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/625/766/","sum":"Noting that the Court’s Fourth Amendment cases recognize that “the police’s physical contact with the defendants’ property” triggers the Fourth Amendment.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"United States v. Mendenhall","cite":"446 U.S. 544","y":1980,"id":"1979/78-1821","sc":1,"sum":"The judgment is reversed, and the case is remanded. Pp. 550-560; 560-566. 596 F. 2d 706, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","1":"16","2":"passim","3":"14"}},{"t":"case","label":"United States v. Salazar","cite":"609 F.3d 1059","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/609/1059/","sum":"Noting that “lower courts … will frequently be confronted with difficult questions concerning precisely when the requisite physical seizure or submission to authority occurs”.","sumSrc":"brief:0","by":{"0":"44"}},{"t":"case","label":"United States v. Steele","cite":"782 F. Supp. 1301","y":1992,"court":"S.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp./782/1301/","by":{"0":"46"}},{"t":"case","label":"United States v. Stover","cite":"808 F.3d 991","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/808/991/","by":{"0":"44"}},{"t":"case","label":"United States v. Watson","cite":"423 U.S. 411","y":1976,"id":"1975/74-538","sc":1,"op":1,"sum":"The Court held that postal inspectors have the power to execute an arrest without a warrant when there is probable cause. Congress has granted this power to several federal agencies, not just the postal service. Because Watson’s arrest was constitutional, the search of his car was not the product of an illegal arrest. The Court held that there was no evidence that Watson was coerced into agreeing to the car search.","sumSrc":"Oyez","by":{"0":"16, 25"}},{"t":"case","label":"Whithead v. Keyes","cite":"85 Mass. 495","y":1862,"url":"https://www.courtlistener.com/c/Mass./85/495/","op":3,"by":{"0":"23","3":"7"}},{"t":"case","label":"Winston v. Lee","cite":"470 U.S. 753","y":1985,"id":"1984/83-1334","sc":1,"ar":1,"sum":"The Court held that below-the-skin surgery represented such an infringement on the expectation of privacy that it must be justified by a compelling need for the evidence that might be produced. Since the state could not demonstrate a compelling need for the bullet in order to make the case against Lee, the Court held that the intrusion on Lee’s privacy vastly outweighed any state interest.","sumSrc":"Oyez","by":{"0":"28","2":"36"}},{"t":"case","label":"Wong Sun v. United States","cite":"371 U.S. 471","y":1963,"id":"1962/36","sc":1,"sum":"The Supreme Court held that the police did not have probable cause to justify the arrests. With regard to Toy, the court should exclude all evidence found during the search because they are the “fruits” of an unlawful search. The unsigned statement was not corroborated, so it gave no basis for conviction. Sun’s unsigned confession and evidence against him were admissible.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":3,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"6, 7","1":"4","2":"10, 17, 22, 29"}},{"t":"case","label":"Brief of the United States, California v. Hodari D.","cite":"1990 WL 10012696","by":{"0":"17"}},{"t":"case","label":"Brief for the United States in Opposition, Huertas v. United States","cite":"138 S. Ct. 1985","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/1985/","sc":1,"by":{"0":"37"}},{"t":"case","label":"Brosseau v. Haugen","cite":"543 U.S. 194","y":2004,"id":"2004/03-1261","sc":1,"sum":"In an 8-1 per curiam decision, the Court held that Brosseau was entitled to qualified immunity because the Court's previous cases did not clearly establish that shooting the fleeing Hogan would have violated his constitutional rights.","sumSrc":"Oyez","by":{"1":"22","3":"15"}},{"t":"case","label":"County of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"op":2,"ar":3,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"1":"12, 16","2":"25, 48"}},{"t":"case","label":"INS v. Delgado","cite":"466 U.S. 210","y":1984,"id":"1983/82-1271","sc":1,"op":1,"ar":1,"sum":"The factory surveys did not result in the seizure of the entire work forces, and the individual questioning of the respondent employees by INS agents concerning their citizenship did not amount to a detention or seizure under the Fourth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"9, 19, 20"}},{"t":"case","label":"Manuel v. City of Joliet","cite":"137 S. Ct. 911","y":2017,"id":"2016/14-9496","sc":1,"sum":"The Court held that an individual’s right to be free from unreasonable search and seizure continues throughout the legal process of a criminal case.","sumSrc":"Oyez","by":{"1":"17","2":"15, 16, 39"}},{"t":"case","label":"Michigan v. Bryant","cite":"562 U.S. 344","y":2011,"id":"2010/09-150","sc":1,"sum":"The Court held that inquiries of wounded victims concerning the perpetrator are non-testimonial if they objectively indicate that the purpose of the interrogation is to enable police assistance to meet an ongoing emergency, and thus, are not afforded heightened protection.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"sum":"The Court ruled that there is an exception to the exclusionary rule for evidence gathered in \"good faith.\"","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Utah v. Strieff","cite":"136 S. Ct. 2056","y":2016,"id":"2015/14-1373","sc":1,"op":1,"sum":"The Court determined that, in the absence of flagrant police misconduct, the discovery of a valid, pre-existing, and untainted arrest warrant attenuated the connection between the unconstitutional investigatory stop and the evidence seized incident to the lawful arrest.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"usc","label":"18 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/18/242","by":{"1":"1"}},{"t":"usc","label":"34 U.S.C. § 12601","url":"https://www.law.cornell.edu/uscode/text/34/12601","by":{"1":"1"}},{"t":"case","label":"Adams v. City of Auburn Hills","cite":"336 F.3d 515","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/336/515/","by":{"2":"17"}},{"t":"case","label":"Alabama v. White","cite":"496 U.S. 325","y":1990,"id":"1989/89-789","sc":1,"sum":"The Court held that the totality of the circumstances provided a sufficiently reasonable suspicion that White possessed illegal drugs. Even though police had no way to confirm the credibility of the caller, police verified many allegations made by the caller about White’s car and movements. Because the police had a reasonable suspicion, the search did not violate the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"op":1,"sum":"The Court ruled that Section 1983 relief for prosecution without probable cause is only valid if the prosecuted party claims Fourth Amendment (pretrial rights) violations.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Am. Legion v. Am. Humanist Ass’n","cite":"139 S. Ct. 2067","y":2019,"id":"2018/17-1717","sc":1,"sum":"The Court held that the display and maintenance of a large memorial cross by a local government does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Anderson v. Creighton","cite":"483 U.S. 635","y":1987,"id":"1986/85-1520","sc":1,"sum":"The Court held that an officer of the law has qualified immunity from civil liability if the actions that officer took “could reasonably have been thought consistent” with the allegedly violated rights. Because Anderson could reasonably believe that his actions were legal, he is entitled to qualified immunity.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Andrade v. City of Burlingame","cite":"519 U.S. 869","y":1996,"url":"https://supreme.justia.com/cases/federal/us/519/869/","sc":1,"by":{"2":"29"}},{"t":"case","label":"Andrade v. City of Burlingame","cite":"847 F. Supp. 760","y":1994,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./847/760/","by":{"2":"29"}},{"t":"case","label":"Ashcroft v. al–Kidd","cite":"563 U.S. 731","y":2011,"id":"2010/10-98","sc":1,"sum":"The Court held that former Attorney General John Ashcroft was entitled to qualified immunity.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Baltimore & Ohio Ry. Co. v. Strube","cite":"111 Md. 119","y":1909,"court":"Md. Ct. App.","url":"https://www.courtlistener.com/c/Md./111/119/","by":{"2":"42"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"38, 44"}},{"t":"case","label":"Bradford v. Wiggins","cite":"516 F.3d 1189","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/516/1189/","by":{"2":"10"}},{"t":"case","label":"Briscoe v. LaHue","cite":"460 U.S. 325","y":1983,"id":"1982/81-1404","sc":1,"sum":"Title 42 U. S. C. § 1983 (1976 ed., Supp. V) does not authorize a convicted state defendant to assert a claim for damages against a police officer for giving perjured testimony at the defendant's criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Britton v. Maloney","cite":"196 F.3d 24","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/196/24/","by":{"2":"15"}},{"t":"case","label":"Brooks v. City of Aurora, Ill.","cite":"653 F.3d 478","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/478/","by":{"2":"18"}},{"t":"case","label":"Brooks v. Gaenzle","cite":"562 U.S. 1200","y":2011,"url":"https://supreme.justia.com/cases/federal/us/562/1200/","sc":1,"by":{"2":"passim"}},{"t":"case","label":"Brower v. Inyo Cnty.","cite":"817 F.2d 540","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/817/540/","by":{"2":"14, 28, 30"}},{"t":"case","label":"Buck v. City of Albuquerque","cite":"2007 WL 9734037","y":2007,"court":"D.N.M. Apr. 11","by":{"2":"26"}},{"t":"case","label":"Cameron v. City of Pontiac","cite":"813 F.2d 782","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/782/","sum":"Finding that even with use of deadly force, where there was no actual physical seizure, “the alleged unreasonableness of the officers’ conduct cannot serve as a basis for a § 1983 cause of action anchored in the Fourth Amendment,” even though the suspect died from other causes independent of the officers’ use of deadly force while fleeing.","sumSrc":"brief:2","by":{"2":"17, 29"}},{"t":"case","label":"Carroll v. Carman","cite":"574 U.S. 13","y":2014,"id":"2014/14-212","sc":1,"sum":"The Court ruled that a government official is entitled to qualified immunity unless his actions violate a statute or constitutional right that was clearly established at the time of the conduct.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"op":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Christopher v. Nestlerode","cite":"373 F. Supp. 2d 503","y":2005,"court":"M.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/373/503/","sum":"Describing arrests that authorize incidental searches.","sumSrc":"brief:3","by":{"2":"40, 41, 42","3":"10"}},{"t":"case","label":"Citizens United v. Federal Election Comm’n","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"City of El Centro v. United States","cite":"922 F.2d 816","y":1990,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/922/816/","by":{"2":"28"}},{"t":"case","label":"City of Escondido v. Emmons","cite":"139 S. Ct. 500","y":2019,"id":"2018/17-1660","sc":1,"sum":"The Ninth Circuit failed to conduct the analysis required by this Court’s precedents in determining whether two Escondido police officers were entitled to qualified immunity.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"30"}},{"t":"case","label":"Cnty. of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"sum":"The Court held that Riverside's actions did not comply with the Gerstein precedent. Justice O'Connor argued that it was the state's burden to demonstrate extraordinary circumstances when delaying probable cause determinations beyond 48 hours. The lower court in this case had placed that responsibility on the accused. Intervening weekends or complicated pretrial proceedings were not legitimate reasons for delay.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Collins v. Virginia","cite":"138 S. Ct. 1663","y":2018,"id":"2017/16-1027","sc":1,"sum":"The Court held that a police officer cannot, under the Fourth Amendment, enter private property in order to conduct a warrantless search of a vehicle parked a few feet from the house.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Cooper v. Rutherford","cite":"503 F. App’x 672","y":2012,"court":"11th Cir. Oct. 12","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/503/672/","by":{"2":"30"}},{"t":"case","label":"Corbitt v. Vickers","cite":"929 F.3d 1304","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/1304/","by":{"2":"17"}},{"t":"case","label":"Dist. of Columbia v. Wesby","cite":"138 S. Ct. 577","y":2018,"id":"2017/15-1485","sc":1,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"2":"30","3":"19"}},{"t":"case","label":"Dockery v. Blackburn","cite":"911 F.3d 458","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/911/458/","by":{"2":"18"}},{"t":"case","label":"Dunigan v. Noble","cite":"390 F.3d 486","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/390/486/","by":{"2":"28"}},{"t":"case","label":"Eldredge v. Town of Falmouth","cite":"622 F.3d 100","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/622/100/","by":{"2":"28"}},{"t":"case","label":"El-Nahal v. Yassky","cite":"835 F.3d 248","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/835/248/","by":{"2":"34"}},{"t":"case","label":"Estate of Shaw v. Sierra","cite":"2009 WL 10703108","y":2009,"court":"N.D. Tex. Sep. 1","by":{"2":"29"}},{"t":"case","label":"Flores v. City of Palacios","cite":"381 F.3d 391","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/381/391/","by":{"2":"19"}},{"t":"case","label":"Florida v. Royer","cite":"460 U.S. 491","y":1983,"id":"1982/80-2146","sc":1,"sum":"The judgment is affirmed. 389 So. 2d 1007, affirmed. JUSTICE WHITE, joined by JUSTICE MARSHALL, JUSTICE POWELL, and JUSTICE STEVENS, concluded that respondent was being illegally detained when he consented to the search of his luggage and that such con- \" 460 U. S. sent was tainted by the illegality and hence was ineffective to justify the search.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9, 20"}},{"t":"case","label":"Franchise Tax Bd. of California v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"French v. Bancroft","cite":"1 Metc. 502","y":1840,"url":"https://www.courtlistener.com/c/Metc./1/502/","by":{"2":"43"}},{"t":"case","label":"Gardner v. Board of Police Comm’rs, for Kansas City","cite":"641 F.3d 947","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/947/","by":{"2":"28, 30"}},{"t":"case","label":"Gorman v. Sharp","cite":"892 F.3d 172","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/172/","by":{"2":"28, 29"}},{"t":"case","label":"Harmon v. City of Pocatello","cite":"2020 WL 104677","y":2020,"court":"D. Idaho Jan. 7","by":{"2":"29, 30"}},{"t":"case","label":"Harris v. Coweta Cnty., Ga.","cite":"433 F.3d 807","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/433/807/","by":{"2":"32"}},{"t":"case","label":"Harrison v. City of Corning","cite":"2016 WL 5871369","y":2016,"court":"W.D.N.Y. Oct. 7","by":{"2":"15"}},{"t":"case","label":"Hart v. Flynn’s Ex’r","cite":"8 Dana 190","y":1839,"court":"Ky. Ct. App.","url":"https://www.courtlistener.com/c/Dana/8/190/","by":{"2":"43"}},{"t":"case","label":"Helvering v. Hallock","cite":"309 U.S. 106","y":1940,"id":"scdb/1939-097","sc":1,"sum":"1. Decedent in his lifetime created a trust providing that the income from the trust property should be paid to his wife during her lifetime, that upon his death, if she survived him, the corpus of the trust should go to her or to other named beneficiaries, but that upon her death, if he survived, the property should revert to himself. The wife survived. Held, that the value of the remainder interest clearly …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Henry v. Purnell","cite":"501 F.3d 374","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/374/","by":{"2":"28"}},{"t":"case","label":"Howerton v. Fletcher","cite":"213 F.3d 171","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/213/171/","by":{"2":"28"}},{"t":"case","label":"Humphrey’s Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Illinois v. Wardlow","cite":"528 U.S. 119","y":2000,"id":"1999/98-1036","sc":1,"sum":"The Court held, 5 to 4, that the police officers did not violate the Fourth Amendment when they stopped Wardlow, because the officer was justified in suspecting that the accused was involved in criminal activity and, therefore, in investigating further.","sumSrc":"Oyez","by":{"2":"11, 12"}},{"t":"case","label":"Jacques v. Sears, Roebuck & Co.","cite":"30 N.Y.2d 466","y":1972,"url":"https://www.courtlistener.com/c/N.Y.2d/30/466/","by":{"2":"42, 43"}},{"t":"case","label":"Jamieson v. Shaw","cite":"772 F.2d 1205","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/1205/","by":{"2":"14"}},{"t":"case","label":"Johnson v. City of Ferguson","cite":"926 F.3d 504","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/504/","by":{"2":"16, 18"}},{"t":"case","label":"Johnson v. State","cite":"689 So.2d 376","y":1997,"court":"Fla. Ct. App.","url":"https://www.courtlistener.com/c/So.2d/689/376/","by":{"2":"26"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Jones v. Norton","cite":"137 S. Ct. 197","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./137/197/","sc":1,"by":{"2":"48"}},{"t":"case","label":"Jones v. Norton","cite":"809 F.3d 564","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/564/","by":{"2":"48"}},{"t":"case","label":"Kerry v. Din","cite":"575 U.S. 86","y":2015,"id":"2014/13-1402","sc":1,"sum":"The Court held that the lack of a detailed explanation for a denial of a visa application does not violate the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"2":"45, 46"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Knick v. Twp. of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"Landol-Rivera v. Cruz Cosme","cite":"906 F.2d 791","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/906/791/","by":{"2":"28"}},{"t":"case","label":"Lara v. Cnty. of San Mateo","cite":"163 F. Supp. 2d 1107","y":2001,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/163/1107/","by":{"2":"26"}},{"t":"case","label":"Long v. Ansell","cite":"293 U.S. 76","y":1934,"id":"scdb/1934-036","sc":1,"op":1,"sum":"1. A Senator of the United States, while in the District of Columbia in attendance at a session of the Senate, is immune under Constitutioh, Art. I, § 6, cl.1, from arrest in a civil case but not from the service of a summons.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Long v. Ansell","cite":"63 App.D.C. 68","y":1934,"court":"D.C. Ct. App.","url":"https://www.courtlistener.com/c/App.D.C./63/68/","by":{"2":"42"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"2":"44"}},{"t":"case","label":"Marquez v. Andrade","cite":"79 F.3d 1153","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/79/1153/","by":{"2":"29"}},{"t":"case","label":"Mazoch v. Carrizales","cite":"733 F. App’x 179","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/733/179/","by":{"2":"29"}},{"t":"case","label":"McCoy v. Harrison","cite":"341 F.3d 600","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/341/600/","by":{"2":"14, 15, 29"}},{"t":"case","label":"McDonough v. Smith","cite":"139 S. Ct. 2149","y":2019,"id":"2018/18-485","sc":1,"sum":"The Court held that the statute of limitations for the petitioner’s § 1983 fabricated evidence claim began to run when the criminal proceedings against him terminated in his favor—that is, when he was acquitted at the end of his second trial.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Medeiros v. O’Connell","cite":"150 F.3d 164","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/150/164/","by":{"2":"28"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Michigan v. Chesternut","cite":"486 U.S. 567","y":1988,"id":"1987/86-1824","sc":1,"op":1,"sum":"The Court held the test of whether a seizure is protected under the Fourth Amendment is dependent on whether a reasonable man would conclude the police restrained his liberty to leave.","sumSrc":"Oyez","by":{"2":"9, 10, 47"}},{"t":"case","label":"Minnesota v. Carter","cite":"525 U.S. 83","y":1998,"id":"1998/97-1147","sc":1,"sum":"The Court held, in an opinion authored by Chief Justice William H. Rehnquist, that people who visit someone's home for a short time do not have the same protection against unreasonable police searches and seizures as do the residents or their overnight guests. Short-term visits for commercial transactions are not protected by the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"sum":"The Court held that after the appointment of an attorney, a defendant does not necessarily need to take additional steps to accept the appointment in order to secure the protections of the Sixth Amendment.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"New York v. Quarles","cite":"467 U.S. 649","y":1984,"id":"1983/82-1213","sc":1,"sum":"The Court held that there is a \"public safety\" exception to the requirement that officers issue Miranda warnings to suspects. Since the police officer's request for the location of the gun was prompted by an immediate interest in assuring that it did not injure an innocent bystander or fall into the hands of a potential accomplice to Quarles, his failure to read the Miranda warning did not violate the Constitution.","sumSrc":"Oyez","by":{"2":"10, 11"}},{"t":"case","label":"Oglesby v. Lesan","cite":"929 F.3d 526","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/526/","by":{"2":"10"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Payton v. New York","cite":"445 U.S. 573","y":1980,"id":"1978/78-5420","sc":1,"op":8,"ar":5,"sum":"Held that the Fourth Amendment, as applied to the states by the Fourteenth Amendment, \"prohibits the police from making a warrantless and nonconsensual entry into a suspect's home in order to make a routine felony arrest.\" Warrantless arrests and searches went to the core of the Fourth Amendment's protection of privacy in a citizen's dwelling.","sumSrc":"Oyez","by":{"2":"37, 45","3":"7"}},{"t":"case","label":"Planned Parenthood of Southeastern Pa. v. Casey","cite":"505 U.S. 833","y":1992,"id":"1991/91-744","sc":1,"sum":"A case in which the Court introduced a new standard of determining the validity of abortion laws by asking if the restrictions place any \"undue burden\" on the mother attempting to abort the fetus. If the restriction is found to do so, it is invalid.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Ploski v. Medenica","cite":"2019 WL 4014193","y":2019,"court":"N.D. Ill. Aug. 26","by":{"2":"9"}},{"t":"case","label":"Posr v. Doherty","cite":"944 F.2d 91","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/944/91/","by":{"2":"40, 41, 43","3":"10"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Rakas v. Illinois","cite":"439 U.S. 128","y":1978,"id":"1978/77-5781","sc":1,"sum":"1. \"Fourth Amendment rights are personal rights which... may not be vicariously asserted,\" Alderman v. United States, 394 U. S. 165, 174, and a person aggrieved by an illegal search and seizure only through the introduction of damaging evidence secured by a search of a third person's premises or property has not had any of his Fourth Amendment rights infringed. The rule of standing to raise vicarious Fourth …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Reed v. Clough","cite":"694 F. App’x 716","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/694/716/","by":{"2":"17"}},{"t":"case","label":"Rhodes v. Walsh","cite":"55 Minn. 542","y":1893,"url":"https://www.courtlistener.com/c/Minn./55/542/","by":{"2":"43"}},{"t":"case","label":"Roberts v. Roberts","cite":"1998 WL 151773","y":1998,"court":"D. Mass. Mar. 17","by":{"2":"41"}},{"t":"case","label":"Sanders v. City of Union Springs","cite":"207 F. App’x 960","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/207/960/","by":{"2":"17"}},{"t":"case","label":"Schultz v. Braga","cite":"455 F.3d 470","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/455/470/","by":{"2":"2, 17"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"op":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"2":"13, 32"}},{"t":"case","label":"Seekamp v. Michaud","cite":"109 F.3d 802","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/109/802/","by":{"2":"28"}},{"t":"case","label":"Segura v. United States","cite":"468 U.S. 796","y":1984,"id":"1983/82-5298","sc":1,"sum":"Acting on information that petitioners probably were trafficking in cocaine from their apartment, New York Drug Enforcement Task Force agents began a surveillance of petitioners. Thereafter, upon observing petitioner Colon deliver a bulky package to one Parra at a restaurant parking lot, while petitioner Segura and one Rivudalla-Vidal visited inside the restaurant, the agents followed Parra and Rivudalla-Vidal to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Skinner v. Ry. Labor Executives’ Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"op":3,"sum":"The Court held that the government's interest in assuring safety on the nation's railroads constituted a \"special need\" which justified a departure from standard warrant and probable-cause requirements in searches.","sumSrc":"Oyez","by":{"2":"8, 33"}},{"t":"case","label":"State v. White, 2013-Ohio-51","cite":"988 N.E.2d 595","url":"https://www.courtlistener.com/c/N.E.2d/988/595/","by":{"2":"2"}},{"t":"case","label":"Stevenson v. State","cite":"287 Md. 504","y":1980,"court":"Md. Ct. App.","url":"https://www.courtlistener.com/c/Md./287/504/","by":{"2":"39"}},{"t":"case","label":"Sullivan v. Bornemann","cite":"384 F.3d 372","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/384/372/","by":{"2":"36"}},{"t":"case","label":"Thomas v. Durastanti","cite":"607 F.3d 655","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/607/655/","by":{"2":"26"}},{"t":"case","label":"Touzin v. Patriarca","cite":"2013 WL 6051062","y":2013,"court":"S.D. Fla. Nov. 14","by":{"2":"22"}},{"t":"case","label":"Travis v. City of Glenn Heights, Tex.","cite":"2013 WL 5508662","y":2013,"court":"N.D. Tex. Oct. 3","by":{"2":"15"}},{"t":"case","label":"U.S. Bancorp Mortgage Co. v. Bonner Mall Partnership","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"United States v. Beamon","cite":"2013 WL 12085684","y":2013,"court":"D.N.M. Mar. 11","by":{"2":"22, 40"}},{"t":"case","label":"United States v. Beamon","cite":"576 F. App’x 753","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/576/753/","by":{"2":"18"}},{"t":"case","label":"United States v. Brignoni-Ponce","cite":"422 U.S. 873","y":1975,"id":"1974/74-114","sc":1,"sum":"The Court held that the Fourth Amendment prohibits Border Patrol agents from stopping a vehicle and questioning its occupants based solely on their appearance.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"United States v. Caira","cite":"833 F.3d 803","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/833/803/","by":{"2":"34"}},{"t":"case","label":"United States v. Drayton","cite":"536 U.S. 194","y":2002,"id":"2001/01-631","sc":1,"sum":"The Court held that the Fourth Amendment does not require police officers to advise bus passengers of their right not to cooperate and to refuse consent to searches. The Court reasoned that, although the officer did not inform the defendants of their right to refuse the search, he did request permission to search and gave no indication consent was required.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"United States v. Eurodif S.A.","cite":"555 U.S. 305","y":2009,"id":"2008/07-1059","sc":1,"sum":"The Court found that the Commerce Department's view of imported low enriched uranium as the sale of goods rather than services was permissible.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"United States v. Griffin","cite":"652 F.3d 793","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/652/793/","by":{"2":"13"}},{"t":"case","label":"United States v. Hernandez","cite":"27 F.3d 1403","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/27/1403/","by":{"2":"18"}},{"t":"case","label":"United States v. Husband","cite":"226 F.3d 626","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/226/626/","by":{"2":"36"}},{"t":"case","label":"United States v. Paetsch","cite":"782 F.3d 1162","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/782/1162/","by":{"2":"2"}},{"t":"case","label":"United States v. Scott","cite":"149 F. Supp. 837","y":1957,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./149/837/","sum":"Noting that “modern writers often define ‘arrest’ for convenience as a formal arrest”.","sumSrc":"brief:3","by":{"2":"43, 45","3":"9, 10"}},{"t":"case","label":"United States v. Smith","cite":"575 F.3d 308","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/575/308/","by":{"2":"13"}},{"t":"case","label":"United States v. Smith","cite":"633 F.3d 889","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/633/889/","by":{"2":"12"}},{"t":"case","label":"United States v. Sweeney","cite":"821 F.3d 893","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/893/","by":{"2":"34"}},{"t":"case","label":"United States v. Va Lerie","cite":"424 F.3d 694","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/424/694/","by":{"2":"33"}},{"t":"case","label":"United States v. Washington","cite":"387 F.3d 1060","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/387/1060/","by":{"2":"10"}},{"t":"case","label":"United States v. Wellbeloved-Stone","cite":"777 F. App’x 605","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/777/605/","by":{"2":"35"}},{"t":"case","label":"Vernonia Sch. Dist. 47J v. Acton","cite":"515 U.S. 646","y":1995,"id":"1994/94-590","sc":1,"sum":"The Court held that an Oregon public school did not violate students' Fourth Amendment rights by mandating random drug tests for student athletes.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Virginia v. Moore","cite":"553 U.S. 164","y":2008,"id":"2007/06-1082","sc":1,"sum":"The Court held unanimously that the search did not violate Moore's constitutional rights. Writing for an eight justice majority (with Justice Ruth Bader Ginsburg concurring), Justice Antonin Scalia stated that the existence of probable cause gives an arresting officer the right to perform a reasonable search of the accused to ensure the officer's safety and to safeguard evidence.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"White v. Pauly","cite":"137 S. Ct. 548","y":2017,"id":"2016/16-67","sc":1,"sum":"The Court determined that an officer’s failure to shout a warning before firing in an ongoing confrontation does not constitute a violation of a clearly established Fourth Amendment right to be free from the excessive use of force.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Wilson v. Arkansas","cite":"514 U.S. 927","y":1995,"id":"1994/94-5707","sc":1,"op":1,"sum":"A unanimous Court held that the common-law \"knock-and announce\" principle forms a part of the Fourth Amendment reasonableness inquiry. \"Given the longstanding common-law endorsement of the practice of announcement, and the wealth of founding-era commentaries, constitutional provisions, statutes, and cases espousing or supporting the knock-and-announce principle,...the Amendment's Framers thought that whether officers announced their presence and authority before entering a dwelling was among the factors to be considered in assessing a search's reasonableness.\" Countervailing law enforcement interests, such as officer safety, may, however, establish the reasonableness of an unannounced entry.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Wyoming v. Houghton","cite":"526 U.S. 295","y":1999,"id":"1998/98-184","sc":1,"sum":"In a 6-to-3 decision the Court held that so long as there is probable cause to search a stopped vehicle, all subsequent searches of its contents are legal as well. The Court added that such searches are especially warranted if aimed at looking into objects or personal belongings capable of concealing items that are the object of the search.","sumSrc":"Oyez","by":{"2":"39, 40"}},{"t":"case","label":"APPELLATE BRIEFS Pet. for Writ of Certiorari, Brooks v. Gaenzle","cite":"2010 WL 4494145","y":2018,"court":"10th Cir. Nov. 5","by":{"2":"23"}},{"t":"case","label":"Respondent’s Brief in Opp. to Pet. for Writ of Certiorari, Brooks v. Gaenzle","cite":"2010 WL 5089145","y":2010,"court":"Dec. 9","by":{"2":"26"}},{"t":"case","label":"Balt. & Ohio R.R. Co. v. Strube","cite":"73 A. 697","y":1909,"court":"Md.","url":"https://www.courtlistener.com/c/A./73/697/","by":{"3":"9"}},{"t":"case","label":"City & County of San Francisco v. Sheehan","cite":"135 S. Ct. 1765","y":2015,"id":"2014/13-1412","sc":1,"op":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"sum":"The Court found that a police officer and narcotic-sniffing dog entering the porch of a home constitutes a search and, without a warrant, is a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Jacques v. Sears, Roebuck & Co.","cite":"285 N.E.2d 871","y":1972,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/285/871/","sum":"Noting that “modern writers often define ‘arrest’ for convenience as a formal arrest”.","sumSrc":"brief:3","by":{"3":"10"}},{"t":"case","label":"Katz v. United States","cite":"389 U.S. 347","y":1967,"id":"1967/35","sc":1,"sum":"The Court found that the government putting a tap on a public payphone is a violation of the users' Fourth Amendment rights.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Kisela v. Hughes","cite":"138 S. Ct. 1148","y":2018,"id":"2017/17-467","sc":1,"sum":"The Court held that a police officer who shot a woman brandishing a knife but not otherwise engaging in threatening behavior was entitled to qualified immunity for his conduct.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"People v. McLean","cite":"68 Mich. 480","y":1888,"url":"https://www.courtlistener.com/c/Mich./68/480/","by":{"3":"10, 11"}},{"t":"case","label":"Rhodes v. Walsh","cite":"57 N.W. 212","y":1893,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./57/212/","by":{"3":"10"}},{"t":"case","label":"Union Pac. Ry. Co. v. Botsford","cite":"141 U.S. 250","y":1891,"id":"scdb/1890-309","sc":1,"sum":"A court of the United States cannot order a plaintiff, in an action for an injury to the person, to submit to a surgical examination in advance of the trial.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"United States v. Carloss","cite":"818 F.3d 988","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/818/988/","by":{"3":"13"}},{"t":"case","label":"United States v. Sprague","cite":"282 U.S. 716","y":1931,"id":"scdb/1930-109","sc":1,"sum":"1. The Eighteenth A&mendm-ent was by lawful proposal and ratification made a part of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}}]};